// Calculate last week's date range
const now = new Date();
const lastMonday = new Date(now);
lastMonday.setDate(lastMonday.getDate() - 7);
lastMonday.setHours(0, 0, 0, 0);

const lastSunday = new Date(lastMonday);
lastSunday.setDate(lastSunday.getDate() + 6);
lastSunday.setHours(23, 59, 59, 999);

const startDate = lastMonday.toISOString();
const endDate = lastSunday.toISOString();
const weekLabel = `${lastMonday.toLocaleDateString('es-ES', { month: 'short', day: 'numeric' })} - ${lastSunday.toLocaleDateString('es-ES', { month: 'short', day: 'numeric' })}`;

return [{ json: { startDate, endDate, weekLabel } }];

const data = $input.all()[0].json;

const formatCurrency = (amount) => {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount || 0);
};

const formatNumber = (num) => {
  return new Intl.NumberFormat('en-US').format(num || 0);
};

const getChangeIndicator = (current, previous) => {
  if (!previous || previous === 0) return '';
  const change = ((current - previous) / previous * 100).toFixed(1);
  if (change > 0) return `<span style="color: #28a745; font-size: 14px;"> ↗ +${change}%</span>`;
  if (change < 0) return `<span style="color: #dc3545; font-size: 14px;"> ↘ ${change}%</span>`;
  return '<span style="color: #999; font-size: 14px;"> → sin cambios</span>';
};

const getMotivationalMessage = (rating, trips) => {
  if (rating >= 4.9) return '🌟 ¡Sos un SÚPER STAR! Tus pasajeros te aman. Seguí así!';
  if (rating >= 4.8) return '⭐ ¡Excelente trabajo! Estás entre los mejores drivers de Cruise.';
  if (rating >= 4.5) return '👍 Muy buen desempeño. Mantené la calidad en cada viaje.';
  if (trips >= 50) return '💪 ¡Impresionante! Completaste muchos viajes esta semana.';
  return '🚀 ¡Seguí adelante! Cada viaje cuenta.';
};

const weeklyEarnings = data.total_earnings || 0;
const weeklyTrips = data.total_trips || 0;
const currentRating = data.average_rating || 0;
const previousEarnings = data.previous_week_earnings || 0;
const previousTrips = data.previous_week_trips || 0;
const previousRating = data.previous_week_rating || 0;

const showMotivation = currentRating >= 4.8;

const htmlContent = `
