    .header h1 { margin: 0 0 10px 0; font-size: 28px; font-weight: 700; }
    .header .week { font-size: 16px; opacity: 0.8; }
    .content { padding: 40px 30px; }
    .greeting { font-size: 20px; color: #333; margin-bottom: 25px; }
    .earnings-highlight { background: linear-gradient(135deg, #28a745 0%, #20c997 100%); color: white; padding: 30px; border-radius: 8px; text-align: center; margin: 25px 0; }
    .earnings-highlight .label { font-size: 14px; opacity: 0.9; margin-bottom: 5px; }
    .earnings-highlight .amount { font-size: 42px; font-weight: 700; margin: 10px 0; }
    .stats-grid { display: table; width: 100%; margin: 25px 0; }
    .stat-row { display: table-row; }
    .stat-label { display: table-cell; padding: 15px 10px; border-bottom: 1px solid #eee; color: #666; font-size: 15px; }
    .stat-value { display: table-cell; padding: 15px 10px; border-bottom: 1px solid #eee; text-align: right; font-weight: 600; color: #333; font-size: 16px; }
    .comparison { background: #f9f9f9; padding: 20px; border-radius: 6px; margin: 25px 0; }
    .comparison h3 { margin: 0 0 15px 0; font-size: 16px; color: #333; }
    .comparison-item { display: flex; justify-content: space-between; margin-bottom: 10px; font-size: 14px; }
    .motivation-box { background: linear-gradient(135deg, #FFD700 0%, #FFA500 100%); color: #1a1a1a; padding: 20px; border-radius: 8px; margin: 25px 0; text-align: center; font-size: 18px; font-weight: 600; }
    .tips { background: #e7f3ff; padding: 20px; border-radius: 6px; margin: 25px 0; border-left: 4px solid #007bff; }
    .tips h3 { margin: 0 0 10px 0; font-size: 16px; color: #004085; }
    .tips ul { margin: 5px 0; padding-left: 20px; }
    .tips li { margin-bottom: 8px; color: #004085; font-size: 14px; }
    .footer { background: #f9f9f9; padding: 20px 30px; text-align: center; color: #999; font-size: 12px; border-top: 1px solid #eee; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Tu Semana en Cruise</h1>
      <div class="week">${data.weekLabel}</div>
    </div>
    <div class="content">
      <div class="greeting">¡Hola ${data.driver_name || 'Driver'}! 👋</div>

      <div class="earnings-highlight">
        <div class="label">Ganaste esta semana</div>
        <div class="amount">${formatCurrency(weeklyEarnings)}</div>
        ${previousEarnings > 0 ? getChangeIndicator(weeklyEarnings, previousEarnings) : ''}
      </div>

      <div class="stats-grid">
        <div class="stat-row">
          <div class="stat-label">🚗 Viajes completados</div>
          <div class="stat-value">${formatNumber(weeklyTrips)}</div>
        </div>
        <div class="stat-row">
          <div class="stat-label">⭐ Rating promedio</div>
          <div class="stat-value">${currentRating.toFixed(2)}</div>
        </div>
        <div class="stat-row">
          <div class="stat-label">💵 Ganancia por viaje</div>
          <div class="stat-value">${weeklyTrips > 0 ? formatCurrency(weeklyEarnings / weeklyTrips) : '$0.00'}</div>
        </div>
        <div class="stat-row">
          <div class="stat-label">⏱️ Horas online</div>
          <div class="stat-value">${data.hours_online || 0}h</div>
        </div>
      </div>

      ${previousEarnings > 0 || previousTrips > 0 ? `
      <div class="comparison">
        <h3>📈 Comparación con semana anterior</h3>
        <div class="comparison-item">
          <span>Ganancias:</span>
          <span>${formatCurrency(previousEarnings)} → ${formatCurrency(weeklyEarnings)} ${getChangeIndicator(weeklyEarnings, previousEarnings)}</span>
        </div>
        <div class="comparison-item">
          <span>Viajes:</span>
          <span>${formatNumber(previousTrips)} → ${formatNumber(weeklyTrips)} ${getChangeIndicator(weeklyTrips, previousTrips)}</span>
        </div>
        <div class="comparison-item">
          <span>Rating:</span>
          <span>${previousRating.toFixed(2)} → ${currentRating.toFixed(2)} ${getChangeIndicator(currentRating, previousRating)}</span>
        </div>
      </div>
      ` : ''}

      ${showMotivation ? `
      <div class="motivation-box">
        ${getMotivationalMessage(currentRating, weeklyTrips)}
      </div>
      ` : ''}

      ${currentRating < 4.5 ? `
      <div class="tips">
        <h3>💡 Tips para mejorar tu rating</h3>
        <ul>
          <li>Saludá amablemente y confirmá el nombre del pasajero</li>
          <li>Mantené el auto limpio y con buen olor</li>
          <li>Ofrecé agua o caramelos (aumenta las propinas)</li>
          <li>Usá la ruta más eficiente y manejá con cuidado</li>
          <li>Evitá conversaciones polémicas, dejá que el pasajero guíe</li>
        </ul>
      </div>
      ` : ''}

      <div style="margin-top: 30px; padding: 20px; background: #f9f9f9; border-radius: 6px; text-align: center;">
        <div style="font-size: 14px; color: #666; margin-bottom: 10px;">Los pagos se procesan todos los lunes</div>
        <div style="font-size: 16px; color: #333; font-weight: 600;">Tu pago de ${formatCurrency(weeklyEarnings)} llegará en 24-48 horas</div>
      </div>
    </div>
    <div class="footer">
      ¿Preguntas sobre tus ganancias? Escribinos a driver-support@cruise.app<br>
      © 2026 Cruise App. Todos los derechos reservados.
    </div>
  </div>
</body>
</html>
`;

return [{ json: { ...data, html: htmlContent, subject: `📊 Tu semana en Cruise: ${formatCurrency(weeklyEarnings)} ganados` } }];
